S={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# enumerate squares & L triominoes
blocks=[]
for r in range(6):
 for c in range(6):
  sq={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if sq<=S: blocks.append(('sq',sq))
for r in range(6):
 for c in range(6):
  for miss in [(0,0),(0,1),(1,0),(1,1)]:
   b={(r+i,c+j) for i in range(2) for j in range(2) if (i,j)!=miss}
   if b<=S: blocks.append((f'L{miss}',b))
sol=[]
def rec(rem, chosen):
 if not rem:
  sol.append(chosen); return
 cell=min(rem)
 for typ,b in blocks:
  if cell in b and b<=rem: rec(rem-b,chosen+[(typ,b)])
rec(S,[])
print(len(sol)); print([[ (t,sorted(b)) for t,b in x] for x in sol[:3]])
